import React, { useState } from 'react';
import './Budgets.css';

const CAT_ICONS = {
  Food:'🍜',Transport:'🚗',Entertainment:'🎬',Shopping:'🛍',Health:'💊',
  Utilities:'⚡',Rent:'🏠',Savings:'💰',Other:'📦',
};
const CATEGORY_COLORS = {
  Food:'#fb923c',Transport:'#60a5fa',Entertainment:'#a78bfa',Shopping:'#f472b6',
  Health:'#4ade80',Utilities:'#2dd4bf',Rent:'#c9a84c',Savings:'#34d399',Other:'#94a3b8',
};

export default function Budgets({ budgets, budgetAlerts, updateBudget, categoryBreakdown }) {
  const [editing, setEditing] = useState(null);
  const [editVal, setEditVal] = useState('');

  const startEdit = (cat) => {
    setEditing(cat);
    setEditVal(String(budgets[cat]));
  };

  const commitEdit = () => {
    if (editing && editVal) updateBudget(editing, editVal);
    setEditing(null);
  };

  const categories = Object.keys(budgets);
  const totalBudget = Object.values(budgets).reduce((s, v) => s + v, 0);
  const totalSpent = Object.values(categoryBreakdown).reduce((s, v) => s + v, 0);
  const overCount = budgetAlerts.filter(a => a.over).length;
  const warnCount = budgetAlerts.filter(a => a.warning).length;

  const fmt = v => `$${Number(v).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

  return (
    <div className="budgets-page">
      <div className="page-header">
        <div>
          <h1 className="page-title">Budgets</h1>
          <p className="page-subtitle">Set limits and track your spending goals</p>
        </div>
      </div>

      {/* Overview */}
      <div className="budget-overview">
        <div className="overview-stat">
          <div className="ov-label">Total Budget</div>
          <div className="ov-val gold">{fmt(totalBudget)}</div>
        </div>
        <div className="overview-divider" />
        <div className="overview-stat">
          <div className="ov-label">Total Spent</div>
          <div className="ov-val red">{fmt(totalSpent)}</div>
        </div>
        <div className="overview-divider" />
        <div className="overview-stat">
          <div className="ov-label">Remaining</div>
          <div className={`ov-val ${totalBudget - totalSpent >= 0 ? 'green' : 'red'}`}>
            {fmt(totalBudget - totalSpent)}
          </div>
        </div>
        <div className="overview-divider" />
        <div className="overview-stat">
          <div className="ov-label">Over Budget</div>
          <div className="ov-val" style={{ color: overCount > 0 ? 'var(--red)' : 'var(--green)' }}>
            {overCount} {overCount === 1 ? 'category' : 'categories'}
          </div>
        </div>
        <div className="overview-divider" />
        <div className="overview-stat">
          <div className="ov-label">Near Limit</div>
          <div className="ov-val" style={{ color: warnCount > 0 ? 'var(--gold-light)' : 'var(--text-2)' }}>
            {warnCount} {warnCount === 1 ? 'category' : 'categories'}
          </div>
        </div>
      </div>

      {/* Budget Cards */}
      <div className="budget-grid">
        {categories.map((cat, i) => {
          const spent = categoryBreakdown[cat] || 0;
          const limit = budgets[cat];
          const pct = limit > 0 ? Math.min((spent / limit) * 100, 100) : 0;
          const over = spent > limit;
          const warning = pct >= 80 && !over;
          const color = CATEGORY_COLORS[cat] || '#94a3b8';

          return (
            <div
              key={cat}
              className={`budget-card ${over ? 'over' : warning ? 'warning' : ''}`}
              style={{ animationDelay: `${i * 40}ms` }}
            >
              <div className="bc-header">
                <div className="bc-left">
                  <span className="bc-icon" style={{ background: `${color}18` }}>{CAT_ICONS[cat] || '📦'}</span>
                  <span className="bc-cat">{cat}</span>
                </div>
                <div className={`bc-status ${over ? 'over' : warning ? 'warning' : 'ok'}`}>
                  {over ? '🔴' : warning ? '🟡' : '🟢'}
                </div>
              </div>

              <div className="bc-track-wrap">
                <div className="bc-track">
                  <div
                    className={`bc-fill ${over ? 'over' : warning ? 'warning' : ''}`}
                    style={{ width: `${pct}%`, background: over ? 'var(--red)' : warning ? 'var(--gold)' : color }}
                  />
                </div>
                <span className="bc-pct">{pct.toFixed(0)}%</span>
              </div>

              <div className="bc-amounts">
                <span className="bc-spent" style={{ color: over ? 'var(--red)' : warning ? 'var(--gold-light)' : color }}>
                  {fmt(spent)} spent
                </span>
                <span className="bc-remaining">
                  {over ? `${fmt(spent - limit)} over` : `${fmt(limit - spent)} left`}
                </span>
              </div>

              <div className="bc-limit-row">
                <span className="bc-limit-label">Budget limit</span>
                {editing === cat ? (
                  <div className="bc-edit-row">
                    <input
                      type="number" className="bc-edit-input"
                      value={editVal}
                      onChange={e => setEditVal(e.target.value)}
                      onKeyDown={e => { if (e.key === 'Enter') commitEdit(); if (e.key === 'Escape') setEditing(null); }}
                      autoFocus
                    />
                    <button className="bc-save-btn" onClick={commitEdit}>✓</button>
                    <button className="bc-cancel-btn" onClick={() => setEditing(null)}>✕</button>
                  </div>
                ) : (
                  <button className="bc-limit-val" onClick={() => startEdit(cat)}>
                    {fmt(limit)} <span className="edit-hint">✎</span>
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
